import { Component, director, instantiate, Node, Prefab, sp, UITransform } from "cc";
import AppAssetBundle from "../utils/AppAssetBundle";
import { GameViewAdapter } from "./GameViewAdapter";

import { WinAnimationView } from "./WinAnimationView";
import { FreeBoardView } from "./FreeBoardView";
import StoreManager from "../store/StoreManager";
import { GameRoot } from "../GameRoot";

// 轉場 spine 資源路徑與播放設定
const TRANSITION_SPINE_PATH = 'resources/spine/transition/transition';
const TRANSITION_ANIMATION = 'animation';
const TRANSITION_DURATION_SEC = 1.1;
const TRANSITION_SCALE = { landscape: 0.5, portrait: 0.4 };

/**
 * 集中管理報獎與免費遊戲獲得兩個動態載入的彈窗與全螢幕轉場
 * 都是單一全螢幕實例 掛在 MiddleNode
 */
export class GamePopupManager {
    constructor(
        private host: Component,
        private getViews: () => GameViewAdapter[],
    ) { }

    // 贏獎彈窗即將出現
    onWinPopup: (() => void) | null = null;

    private winAnimationViewInstance: WinAnimationView | null = null;
    private freeBoardViewInstance: FreeBoardView | null = null;

    get winAnimationView(): WinAnimationView | null { return this.winAnimationViewInstance; }

    /** 依目前方向挑 adapter 綁的 prefab 沒綁就取另一邊 */
    private pickPrefab(select: (v: GameViewAdapter) => Prefab | null): Prefab | null {
        const views = this.getViews();
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const adapter = views.find(view => view.node.name === adapterName) ?? views[0];
        return (adapter && select(adapter)) ?? views.map(select).find(prefab => prefab) ?? null;
    }

    /** 建立單一實例並掛到 MiddleNode */
    private mountSingle(prefab: Prefab): Node {
        const node = instantiate(prefab);
        // 掛在 MiddleNode 找不到退回 Canvas
        const parent = director.getScene()?.getComponentInChildren(GameRoot)?.middleNode ?? director.getScene()?.getChildByName('Canvas') ?? this.host.node;
        parent.addChild(node);
        node.setSiblingIndex(999);
        node.active = false;
        return node;
    }

    private async loadWinAnimation(): Promise<WinAnimationView> {
        const prefab = this.pickPrefab(v => v.winAnimationPrefab);
        if (!prefab) throw new Error('[Popup] winAnimationPrefab 未綁定');
        return this.mountSingle(prefab).getComponent(WinAnimationView)!;
    }

    private _winAnimPromise: Promise<WinAnimationView> | null = null;
    async getWinAnimation(): Promise<WinAnimationView> {
        if (this.winAnimationViewInstance) return this.winAnimationViewInstance;
        if (!this._winAnimPromise) {
            this._winAnimPromise = (async () => {
                const t0 = performance.now();
                console.log(`[Popup] winAnimationView: start loading`);
                const view = await this.loadWinAnimation();
                this.winAnimationViewInstance = view;
                console.log(`[Popup] winAnimationView: ready ${(performance.now() - t0).toFixed(0)}ms`);
                return view;
            })();
        }
        return this._winAnimPromise;
    }

    /** 背景 preload：只下載到 bundle cache，不 instantiate */
    async preloadAll(): Promise<void> {
        const bundle = await AppAssetBundle.getInstance('1002').getBundle();
        if (!bundle) return;
        const set = new Set<string>();
        for (const v of this.getViews()) {
            set.add(v.buyFeaturePrefabPath || 'resources/prefabs/buyFeaturePopup');
        }
        for (const path of set) {
            bundle.load(path, Prefab, (err) => {
                if (err) console.warn(`[Popup] preload failed: ${path}`, err);
                else console.log(`[Popup] preloaded: ${path}`);
            });
        }
    }

    async showWinAnimation(...args: Parameters<WinAnimationView['show']>): Promise<void> {
        this.onWinPopup?.();
        const view = await this.getWinAnimation();
        await view.show(...args);
    }

    /** Jackpot 已移除：保留空 stub，避免遊戲流程呼叫端炸掉 */
    showJackpotOnAll(..._args: unknown[]): Promise<void> {
        return Promise.resolve();
    }

    private _freeBoardPromise: Promise<FreeBoardView> | null = null;
    async getFreeBoard(): Promise<FreeBoardView> {
        if (this.freeBoardViewInstance) return this.freeBoardViewInstance;
        if (!this._freeBoardPromise) {
            this._freeBoardPromise = (async () => {
                const prefab = this.pickPrefab(v => v.freeBoardPrefab);
                if (!prefab) throw new Error('[Popup] freeBoardPrefab 未綁定');
                const node = this.mountSingle(prefab);
                this.freeBoardViewInstance = node.getComponent(FreeBoardView)!;
                return this.freeBoardViewInstance;
            })();
        }
        return this._freeBoardPromise;
    }

    async showFreeBoard(): Promise<void> {
        this.onWinPopup?.();
        const view = await this.getFreeBoard();
        await view.show();
    }

    private transitionSkel: sp.Skeleton | null = null;
    private _transitionPromise: Promise<sp.Skeleton> | null = null;

    /** 建立橫直版共用的轉場 spine 掛在 MiddleNode */
    private getTransition(): Promise<sp.Skeleton> {
        if (this.transitionSkel?.isValid) return Promise.resolve(this.transitionSkel);
        if (!this._transitionPromise) {
            this._transitionPromise = (async () => {
                const data = await AppAssetBundle.getInstance('1002').loadAsset(TRANSITION_SPINE_PATH, sp.SkeletonData);
                const node = new Node('transition');
                node.layer = this.host.node.layer;
                node.addComponent(UITransform);
                const skel = node.addComponent(sp.Skeleton);
                skel.skeletonData = data;
                skel.premultipliedAlpha = false;
                const parent = director.getScene()?.getComponentInChildren(GameRoot)?.middleNode ?? director.getScene()?.getChildByName('Canvas') ?? this.host.node;
                parent.addChild(node);
                node.active = false;
                this.transitionSkel = skel;
                return skel;
            })();
        }
        return this._transitionPromise;
    }

    /** 背景預載轉場資源 */
    preloadTransition(): void {
        this.getTransition().catch((e) => console.warn('[Popup] transition preload failed', e));
    }

    /**
     * 在所有彈窗之上播放轉場
     *
     * @returns 轉場播完時完成
     */
    async playTransition(): Promise<void> {
        const skel = await this.getTransition();
        const node = skel.node;
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const scale = isPortrait ? TRANSITION_SCALE.portrait : TRANSITION_SCALE.landscape;
        node.setScale(scale, scale, 1);
        node.setSiblingIndex(node.parent!.children.length - 1);
        node.active = true;
        skel.setAnimation(0, TRANSITION_ANIMATION, false);
        await new Promise<void>((resolve) => {
            this.host.scheduleOnce(() => {
                if (node.isValid) node.active = false;
                resolve();
            }, TRANSITION_DURATION_SEC);
        });
    }
}
