import { _decorator, Component, Label, sp } from 'cc';

const { ccclass, property } = _decorator;

@ccclass('1002/WinFloatLabel')
export class WinFloatLabel extends Component {
    @property(sp.Skeleton)
    spine: sp.Skeleton = null!;

    @property(Label)
    label: Label = null!;

    @property({ tooltip: 'Spine 動畫名' })
    animName: string = 'animation';

    play(amount: number): void {
        this.label.string = `${amount.toFixed(2)}`;
        const trackEntry = this.spine.setAnimation(0, this.animName, false);

        let done = false;
        const finish = () => {
            if (done) return;
            done = true;
            this.spine.setCompleteListener(null);
            this.unscheduleAllCallbacks();
            if (this.node.isValid) this.node.destroy();
        };

        this.spine.setCompleteListener((entry) => {
            if (entry === trackEntry) finish();
        });

        const dur = trackEntry?.animation?.duration ?? 1.0;
        this.scheduleOnce(finish, dur + 0.1);
    }
}
