const DEFAULT_DEBUG_NORMAL_SYMBOLS: [number, string][] = Array.from({ length: 9 }, (_, i) => [i + 1, `sym${i + 1}`]);

export function getSymbolDebugOptions(symbols?: SlotApiSymbolInfo[] | null): [number, string][] {
    const normals = (symbols ?? []).filter((s) => s.kind === 'normal');
    if (normals.length === 0) return DEFAULT_DEBUG_NORMAL_SYMBOLS;
    return normals
        .slice()
        .sort((a, b) => a.id - b.id)
        .map((s) => [s.id, s.name]);
}

// ===== 玩家端 API v5.1（slot-integration.md）：進場 =====

/** 回應信封；成功時 `code` 為 0 */
export interface SlotApiEnvelope<T = unknown> {
    code: number;
    message?: string;
    trace_id?: string;
    /** 只在 4016 */
    support_ref?: string;
    /** 只在 4023 */
    latest_step_id?: string;
    data?: T;
}

/** 失敗來源：業務碼、HTTP 401（session 失效）、HTTP 層失敗、網路或逾時 */
export type SlotApiErrorKind = 'business' | 'unauthorized' | 'http' | 'network';

/** 玩家端 API 失敗。判斷邏輯只看 `kind` 與 `code`，`message` 不保證穩定 */
export class SlotApiHttpError extends Error {
    constructor(
        public readonly kind: SlotApiErrorKind,
        /** 業務錯誤碼（附錄 A）；沒有 code 的 401、503、網路錯誤為 0 */
        public readonly code: number,
        message: string,
        public readonly httpStatus: number = 0,
        public readonly supportRef?: string,
        public readonly latestStepId?: string,
        /** 429 的 `Retry-After`（秒） */
        public readonly retryAfterSec?: number
    ) {
        super(message);
        this.name = 'SlotApiHttpError';
    }
}

