import { AudioClip, AudioSource, Game, game, Node, tween, Tween } from 'cc';
import AppUtility from '../utils/AppUtility';
import AppAssetBundle from '../utils/AppAssetBundle';
import { BASE_EVENT_TYPE, baseRuntimeEventBus } from '../events/BaseRuntimeEventBus';
import { getSettingStore } from '../store/RootStoreHooks';

/**
 * AppAudio
 * 原生替代 KYCocosSDK/Module/KYAudio.ts，方法簽名 1:1 對應，
 * 供逐步替換 import 路徑使用，KYCocosSDK 內檔案本身不受影響。
 * 內部依賴已改用原生的 AppUtility / AppAssetBundle。

 * 統一管理當前遊戲 Bundle 的背景音樂 音效與使用者音量設定
 */

const MAX_MUSIC_TRACKS = 2;
const MIN_PLAYBACK_RATE = 0.25;
const MAX_PLAYBACK_RATE = 4;

/**
 * 音效播放器被指派之後，多久之內不能再被別人挑走（毫秒）。
 *
 * `AudioSource` 換上新音檔後要等播放器非同步載入完，`playing` 才會變 true；這段期間只看 `playing`
 * 會把它當成空的，同一個 tick 送出的幾個音效會全部擠進同一個播放器，一個蓋一個只剩最後一支
 * （見 entry `docs/agent-pitfalls.md` #50）。實測載入只要幾毫秒，500 是保守值；過了這段時間就回到
 * 只看 `playing`，播放器不會因為某次沒播起來而被永遠佔住。
 */
const SFX_CLAIM_GRACE_MS = 500;

/** 每個音效播放器最近一次被指派的時間（`performance.now()`） */
const sfxClaimedAt = new WeakMap<AudioSource, number>();

/**
 * 這個播放器是不是剛被指派、還在等播放器載入。
 *
 * @param source 要查的播放器。
 * @param now 目前時間（`performance.now()`）。
 * @returns 還在保留期內時為 true。
 */
function isSfxClaimPending(source: AudioSource, now: number): boolean {
    const claimedAt = sfxClaimedAt.get(source);
    return claimedAt !== undefined && now - claimedAt < SFX_CLAIM_GRACE_MS;
}

function setSourcePlaybackRateIfSupported(source: AudioSource, rate: number): void {
    const compatibleSource = source as AudioSource & { playbackRate?: number };
    if ('playbackRate' in compatibleSource) compatibleSource.playbackRate = rate;
}

// 固定 1 倍播放的音效播放器 setPlaybackRate 不調整它們
const unscaledSources = new WeakSet<AudioSource>();

// playEffect 的選項物件
export interface PlayEffectOptions {
    volume?: number;
    allowOverlap?: boolean;
    /** 播放前先停止這組音效 適合每次都要觸發但尾音不能互相疊加的音效 */
    interruptPaths?: string[];
    /** 固定 1 倍播放 不隨整體加速變動 */
    ignorePlaybackRate?: boolean;
}

/**
 * Entry 與 SubGame 會各自編譯一份 AppAudio 模組，但實際運行在同一個 JS Runtime。
 * 播放器與播放狀態必須共用，否則兩份模組會各自建立 AudioSource pool，loop 音效也
 * 無法互相去重。AudioClip 快取仍留在各 bundle 的 AppAudio instance 裡。
 */
interface AppAudioSharedState {
    instanceMap: Record<string, AppAudio>;
    currBundleName: string;
    audioNode: Node | null;
    musicTracks: AudioSource[];
    musicTrackPaths: (string | null)[];
    musicPauseRefCount: Map<number, number>;
    sfxSources: AudioSource[];
    maxSfxSources: number;
    playbackRate: number;
    visibilityBound: boolean;
    musicFadeCallbacks: Map<AudioSource, (() => void)[]>;
    loopRequestGen: Map<string, number>;
    musicVolume: number;
    sfxVolume: number;
}

const APP_AUDIO_STATE_KEY = '__APP_AUDIO_STATE__';

function getAppAudioSharedState(): AppAudioSharedState {
    const scope = globalThis as typeof globalThis & { [APP_AUDIO_STATE_KEY]?: AppAudioSharedState };
    if (!scope[APP_AUDIO_STATE_KEY]) {
        scope[APP_AUDIO_STATE_KEY] = {
            instanceMap: {},
            currBundleName: '',
            audioNode: null,
            musicTracks: [],
            musicTrackPaths: [],
            musicPauseRefCount: new Map<number, number>(),
            sfxSources: [],
            maxSfxSources: 10,
            playbackRate: 1,
            visibilityBound: false,
            musicFadeCallbacks: new Map<AudioSource, (() => void)[]>(),
            loopRequestGen: new Map<string, number>(),
            musicVolume: 1,
            sfxVolume: 1,
        };
    }
    return scope[APP_AUDIO_STATE_KEY]!;
}

export default class AppAudio {
    private static get instanceMap(): Record<string, AppAudio> { return getAppAudioSharedState().instanceMap; }
    private static get currBundleName(): string { return getAppAudioSharedState().currBundleName; }
    private static set currBundleName(value: string) { getAppAudioSharedState().currBundleName = value; }

    /**
     * 播放用的節點／AudioSource pool 各 bundle 之間切換的只有音量設定
     */
    private static get audioNode(): Node | null { return getAppAudioSharedState().audioNode; }
    private static set audioNode(value: Node | null) { getAppAudioSharedState().audioNode = value; }
    // 音樂：多軌 AudioSource
    private static get musicTracks(): AudioSource[] { return getAppAudioSharedState().musicTracks; }
    private static get musicTrackPaths(): (string | null)[] { return getAppAudioSharedState().musicTrackPaths; }
    private static get musicPauseRefCount(): Map<number, number> { return getAppAudioSharedState().musicPauseRefCount; }
    // 音效播放器池 (SFX)
    private static get sfxSources(): AudioSource[] { return getAppAudioSharedState().sfxSources; }
    private static get maxSfxSources(): number { return getAppAudioSharedState().maxSfxSources; }
    private static get playbackRate(): number { return getAppAudioSharedState().playbackRate; }
    private static set playbackRate(value: number) { getAppAudioSharedState().playbackRate = value; }
    private static get visibilityBound(): boolean { return getAppAudioSharedState().visibilityBound; }
    private static set visibilityBound(value: boolean) { getAppAudioSharedState().visibilityBound = value; }
    private static get musicFadeCallbacks(): Map<AudioSource, (() => void)[]> { return getAppAudioSharedState().musicFadeCallbacks; }
    /** loop 音效載入中的請求世代，見 playLoopEffect/stopLoopEffect */
    private static get loopRequestGen(): Map<string, number> { return getAppAudioSharedState().loopRequestGen; }

    // 音量是整個 App 的使用者設定，跨 Entry/SubGame 共用；靜音由音量是否為 0 衍生。
    private get _musicVolume(): number { return getAppAudioSharedState().musicVolume; }
    private set _musicVolume(value: number) { getAppAudioSharedState().musicVolume = value; }
    private get _sfxVolume(): number { return getAppAudioSharedState().sfxVolume; }
    private set _sfxVolume(value: number) { getAppAudioSharedState().sfxVolume = value; }

    // 音頻資源快取（各 bundle 分開快取）
    private audioClips: Map<string, AudioClip> = new Map();

    private bundleName: string;

    private constructor(bundleName: string) {
        this.bundleName = bundleName;
    }

    public static getInstance(bundleName: string = AppAudio.currBundleName): AppAudio {
        if (!bundleName) {
            throw new Error('[AppAudio] 尚未設定目前遊戲 Bundle');
        }

        if (AppAudio.currBundleName && AppAudio.currBundleName !== bundleName) {
            const current = AppAudio.instanceMap[AppAudio.currBundleName];
            current?.stopMusic();
            current?.stopAllSfx();
        }

        AppAudio.currBundleName = bundleName;
        if (!AppAudio.instanceMap[bundleName]) {
            AppAudio.instanceMap[bundleName] = new AppAudio(bundleName);
        }
        return AppAudio.instanceMap[bundleName];
    }

    /** 離開子遊戲時停止目前遊戲的所有音樂與音效 */
    public static stopCurrent(): void {
        if (!AppAudio.currBundleName) return;
        const current = AppAudio.instanceMap[AppAudio.currBundleName];
        current?.stopMusic();
        current?.stopAllSfx();
    }

    initAudio(_parentNode?: Node) {
        if (!AppAudio.audioNode?.isValid) {
            AppAudio.audioNode = new Node('AppAudio');
            // 注意：director.addPersistRootNode() 要求節點當下必須是場景根層級（無 parent），
            // 若先掛到 parentNode 底下再呼叫，會 persist 失敗（跨場景時節點就被銷毀），
            // 所以這裡刻意不 parent 到任何場景節點下，直接以獨立根節點身分常駐。
            AppUtility.setStaticNode(AppAudio.audioNode);
            AppAudio.createMusicTracks();
            AppAudio.createSfxPool();
            AppAudio.listenVisibility();
        }
    }

    // ==================== 音樂（多軌 AudioSource）====================

    private static createMusicTracks() {
        for (let i = 0; i < MAX_MUSIC_TRACKS; i++) {
            const node = new Node(`Music_${i}`);
            node.parent = AppAudio.audioNode;
            const source = node.addComponent(AudioSource);
            source.loop = true;
            source.playOnAwake = false;
            setSourcePlaybackRateIfSupported(source, AppAudio.playbackRate);
            AppAudio.musicTracks.push(source);
            AppAudio.musicTrackPaths.push(null);
        }
    }

    private static listenVisibility(): void {
        if (AppAudio.visibilityBound) return;
        AppAudio.visibilityBound = true;
        game.on(Game.EVENT_HIDE, () => {
            for (const track of AppAudio.musicTracks) {
                track.pause();
            }
        });
        game.on(Game.EVENT_SHOW, () => {
            for (let i = 0; i < AppAudio.musicTracks.length; i++) {
                if (AppAudio.musicTrackPaths[i]) {
                    AppAudio.musicTracks[i].play();
                }
            }
        });
    }

    /**
     * 在指定軌道播放音樂
     * @param path 音頻路徑
     * @param track 軌道 index（預設 0）
     */
    async playMusic(path: string, track: number = 0) {
        if (track >= AppAudio.musicTracks.length) return;
        const source = AppAudio.musicTracks[track];
        source.stop();
        AppAudio.musicTrackPaths[track] = path;

        const clip = await this.tryLoadAudio(path);
        if (!clip) return;
        // await 期間如果這個 track 被換了，放棄
        if (AppAudio.musicTrackPaths[track] !== path) return;

        source.clip = clip;
        source.volume = this._musicVolume;
        source.play();
        console.log(`[AppAudio] 播放音樂 [${track}]: ${path}`);
    }

    /**
     * 停止指定軌道的音樂
     * @param track 軌道 index，不傳則停全部
     */
    stopMusic(track?: number) {
        if (track !== undefined) {
            if (track < AppAudio.musicTracks.length) {
                AppAudio.musicTracks[track].stop();
                AppAudio.musicTrackPaths[track] = null;
            }
        } else {
            for (let i = 0; i < AppAudio.musicTracks.length; i++) {
                AppAudio.musicTracks[i].stop();
                AppAudio.musicTrackPaths[i] = null;
            }
        }
    }

    /** 暫停音樂 */
    pauseMusic(track?: number) {
        const indexes = track !== undefined ? [track] : AppAudio.musicTracks.map((_, i) => i);
        for (const i of indexes) {
            const t = AppAudio.musicTracks[i];
            if (!t || !AppAudio.musicTrackPaths[i]) continue;
            const count = AppAudio.musicPauseRefCount.get(i) ?? 0;
            if (count === 0) {
                if (!t.playing) continue;
                Tween.stopAllByTarget(t);
                t.pause();
            }
            AppAudio.musicPauseRefCount.set(i, count + 1);
        }
    }

    /** 恢復音樂 */
    resumeMusic(track?: number) {
        const indexes = track !== undefined ? [track] : Array.from(AppAudio.musicPauseRefCount.keys());
        for (const i of indexes) {
            const count = AppAudio.musicPauseRefCount.get(i);
            if (!count) continue;
            if (count > 1) {
                AppAudio.musicPauseRefCount.set(i, count - 1);
                continue;
            }
            AppAudio.musicPauseRefCount.delete(i);
            AppAudio.musicTracks[i]?.play();
        }
    }

    /**
     * 漸變音樂音量到目標比例
     * @param ratio 目標比例（0~1），相對於 musicVolume
     * @param duration 漸變時間（秒）
     * @param onComplete 所有正在播放的音軌都淡完後呼叫一次
     */
    fadeMusicVolume(ratio: number, duration: number = 0.5, onComplete?: () => void): void {
        const targetVol = this._musicVolume * ratio;
        const playingTracks = AppAudio.musicTracks.filter((track) => track.playing);
        if (playingTracks.length === 0) {
            onComplete?.();
            return;
        }
        let pending = playingTracks.length;
        const done = () => {
            pending--;
            if (pending === 0) onComplete?.();
        };
        for (const track of playingTracks) {
            // 同一個 track 若有前一次還沒完成的 fade（例如橫/直版 WinAnimationView 同時各自呼叫一次），
            // 把它的完成回呼一起累積起來，換新 tween 蓋掉舊的時不要漏掉前一個呼叫者的 onComplete，
            // 不然前一個呼叫者的介面會卡住永遠關不掉。
            const callbacks = AppAudio.musicFadeCallbacks.get(track) ?? [];
            callbacks.push(done);
            AppAudio.musicFadeCallbacks.set(track, callbacks);

            this.fadeVolume(track, targetVol, duration, () => {
                const pendingCallbacks = AppAudio.musicFadeCallbacks.get(track) ?? [];
                AppAudio.musicFadeCallbacks.delete(track);
                pendingCallbacks.forEach((cb) => cb());
            });
        }
    }

    /** 共用取消殘留 淡到 targetVolume */
    private fadeVolume(target: AudioSource, targetVolume: number, duration: number, onComplete?: () => void): void {
        Tween.stopAllByTarget(target);
        tween(target)
            .to(duration, { volume: targetVolume }, { easing: 'linear' })
            .call(() => onComplete?.())
            .start();
    }

    // ==================== 資源載入 ====================

    private async loadAudio(path: string): Promise<AudioClip> {
        if (this.audioClips.has(path)) {
            return this.audioClips.get(path)!;
        }
        const bundle = await AppAssetBundle.getInstance(this.bundleName);
        const clip = await bundle.loadAudioClip(path);
        this.audioClips.set(path, clip);
        return clip;
    }

    private static warnedMissing = new Set<string>();

    /**
     * 載入音檔 失敗回 null
     *
     * @param path 音檔路徑
     * @returns 音檔 失敗為 null
     */
    private async tryLoadAudio(path: string): Promise<AudioClip | null> {
        if (AppAudio.warnedMissing.has(path)) return null;
        try {
            return await this.loadAudio(path);
        } catch (e) {
            if (!AppAudio.warnedMissing.has(path)) {
                AppAudio.warnedMissing.add(path);
                console.warn(`[AppAudio] 音檔載入失敗 略過播放: ${path}`);
            }
            return null;
        }
    }

    /** 回傳 Promise，呼叫端要不要等全部載完再繼續自行決定，不 await 的話行為跟以前一樣是背景載入 */
    async preloadAll(paths: string[]): Promise<void> {
        await Promise.all(paths.map((path) => this.loadAudio(path).catch(() => {})));
    }

    // ==================== 音效池建立 ====================

    private static createSfxPool() {
        for (let i = 0; i < AppAudio.maxSfxSources; i++) {
            const sfxNode = new Node(`SFX_${i}`);
            sfxNode.parent = AppAudio.audioNode;
            const source = sfxNode.addComponent(AudioSource);
            source.loop = false;
            source.playOnAwake = false;
            setSourcePlaybackRateIfSupported(source, AppAudio.playbackRate);
            AppAudio.sfxSources.push(source);
        }
    }

    // ==================== 音效 (SFX) 控制 ====================

    /**
     * 從池裡挑一個可用的音效播放器，挑中的在這裡就登記，呼叫端接著換音檔、`play()`。
     *
     * 剛被指派、還在載入的播放器也算「在播」（見 {@link SFX_CLAIM_GRACE_MS}）。全部都忙時會搶一個
     * 非 loop 的來蓋掉——寧可截斷一個一次性音效，也不要把正在播的 loop 搶走造成殘留。
     *
     * @returns 可用的播放器；池是空的時候才會是 null。
     */
    private getAvailableSfxSource(): AudioSource | null {
        const now = performance.now();
        const source =
            AppAudio.sfxSources.find((s) => !s.playing && !s.loop && !isSfxClaimPending(s, now)) ??
            AppAudio.sfxSources.find((s) => !s.loop && !isSfxClaimPending(s, now)) ??
            AppAudio.sfxSources.find((s) => !s.loop) ??
            AppAudio.sfxSources[0] ??
            null;
        if (source) sfxClaimedAt.set(source, now);
        return source;
    }

    async playEffect(path: string, opts?: PlayEffectOptions) {
        const clip = await this.tryLoadAudio(path);
        if (!clip) return;
        const interruptClips = opts?.interruptPaths
            ?.map((interruptPath) => this.audioClips.get(interruptPath))
            .filter((interruptClip): interruptClip is AudioClip => interruptClip !== undefined);
        if (interruptClips?.length) {
            for (const source of AppAudio.sfxSources) {
                if (!source.loop && source.clip && interruptClips.includes(source.clip)) source.stop();
            }
        } else if (opts?.allowOverlap === false) {
            const dup = AppAudio.sfxSources.find((s) => !s.loop && s.clip === clip);
            dup?.stop();
        }
        const source = this.getAvailableSfxSource();
        if (!source) return;
        Tween.stopAllByTarget(source); // 清掉殘留
        source.stop();
        source.clip = clip;
        source.loop = false;
        if (opts?.ignorePlaybackRate) unscaledSources.add(source);
        else unscaledSources.delete(source);
        setSourcePlaybackRateIfSupported(source, opts?.ignorePlaybackRate ? 1 : AppAudio.playbackRate);
        source.volume = this.sfxMuted ? 0 : (opts?.volume ?? this._sfxVolume);
        source.play();
    }

    /** 停止已播及待播音效，同時取消尚在載入音檔的循環請求。 */
    stopAllSfx() {
        for (const [path, generation] of AppAudio.loopRequestGen) {
            AppAudio.loopRequestGen.set(path, generation + 1);
        }
        AppAudio.sfxSources.forEach((source) => {
            source.stop();
            source.loop = false;
        });
    }

    private fadeOutSource(source: AudioSource, duration = 0.5) {
        this.fadeVolume(source, 0, duration, () => source.stop());
    }

    /** 0.5秒fade out */
    stopEffectWithFade(path: string, duration = 0.5) {
        const clip = this.audioClips.get(path);
        const source = AppAudio.sfxSources.find((s) => s.playing && s.clip === clip);
        if (source) this.fadeOutSource(source, duration);
    }

    /** 批次仲裁 從候選音效裡挑優先度最高的 */
    playHighestPriority(candidates: { path: string; priority: number }[], allowOverlap = true) {
        if (candidates.length === 0) return;
        const winner = candidates.reduce((a, b) => (b.priority > a.priority ? b : a));
        this.playEffect(winner.path, { allowOverlap });
    }

    async playLoopEffect(path: string, volume?: number) {
        for (const source of AppAudio.sfxSources) {
            if (source.loop && source.clip && source.clip === this.audioClips.get(path)) {
                return;
            }
        }
        // 音檔還沒載入完成時就可能被 stopLoopEffect（或另一次 playLoopEffect）取代，
        // 用 generation 記錄「這是第幾次請求」，await 結束後如果不是最新的請求就放棄播放，
        // 不然會變成停輪指令先到、音效還沒載完，載完後才開始播、永遠停不掉的殘留音。
        const gen = (AppAudio.loopRequestGen.get(path) ?? 0) + 1;
        AppAudio.loopRequestGen.set(path, gen);
        const clip = await this.tryLoadAudio(path);
        if (!clip || AppAudio.loopRequestGen.get(path) !== gen) return; // 載入期間被取消/取代，放棄
        const source = this.getAvailableSfxSource();
        if (!source) return;
        Tween.stopAllByTarget(source); // 清掉殘留
        source.stop();
        source.clip = clip;
        source.loop = true;
        unscaledSources.delete(source);
        setSourcePlaybackRateIfSupported(source, AppAudio.playbackRate);
        source.volume = this.sfxMuted ? 0 : (volume ?? this._sfxVolume);
        source.play();
        console.log(`[AppAudio] 播放循環音效: ${path}`);
    }

    setLoopEffectVolume(path: string, volume: number) {
        const clip = this.audioClips.get(path);
        for (const source of AppAudio.sfxSources) {
            if (source.playing && source.loop && source.clip === clip) {
                source.volume = volume;
                return;
            }
        }
    }

    /**
     * 停止循環音效
     * @param path
     * @param endPath 收尾音效
     * @returns
     */
    stopLoopEffect(path: string, endPath?: string) {
        AppAudio.loopRequestGen.set(path, (AppAudio.loopRequestGen.get(path) ?? 0) + 1); // 取消還在載入中、尚未真正開始播放的請求
        const clip = this.audioClips.get(path);
        for (const source of AppAudio.sfxSources) {
            // clip 設定後播放器仍會非同步載入；playing=false 也必須排入 STOP。
            if (clip && source.loop && source.clip === clip) {
                source.stop();
                source.loop = false;
                console.log(`[AppAudio] 停止循環音效: ${path}`);
                if (endPath) this.playEffect(endPath);
                return;
            }
        }
    }

    // ==================== 音量控制 ====================

    set musicVolume(volume: number) {
        this._musicVolume = Math.max(0, Math.min(1, volume));
        for (const track of AppAudio.musicTracks) {
            if (!track.playing) continue;
            // 直接設定音量優先度高於進行中的 fade 取消掉 避免下一幀被 fade 蓋回去
            Tween.stopAllByTarget(track);
            const pendingCallbacks = AppAudio.musicFadeCallbacks.get(track);
            if (pendingCallbacks) {
                AppAudio.musicFadeCallbacks.delete(track);
                pendingCallbacks.forEach((cb) => cb());
            }
            track.volume = this._musicVolume;
        }
    }

    get musicVolume(): number {
        return this._musicVolume;
    }

    set sfxVolume(volume: number) {
        this._sfxVolume = Math.max(0, Math.min(1, volume));
        AppAudio.sfxSources.forEach((source) => {
            if (source.playing) source.volume = this._sfxVolume;
        });
    }

    get sfxVolume(): number {
        return this._sfxVolume;
    }

    /** 設定全部音樂與音效的播放倍率 */
    setPlaybackRate(rate: number): void {
        AppAudio.playbackRate = Number.isFinite(rate)
            ? Math.max(MIN_PLAYBACK_RATE, Math.min(MAX_PLAYBACK_RATE, rate))
            : 1;
        for (const track of AppAudio.musicTracks) {
            setSourcePlaybackRateIfSupported(track, AppAudio.playbackRate);
        }
        for (const source of AppAudio.sfxSources) {
            if (unscaledSources.has(source)) continue;
            setSourcePlaybackRateIfSupported(source, AppAudio.playbackRate);
        }
    }

    // 靜音是音量的衍生狀態 統一交給 SettingStore 持久化並跨場景同步
    set musicMuted(muted: boolean) {
        const store = getSettingStore();
        if (store) store.setMusicVolumeStore(muted ? 0 : 1);
        else this.musicVolume = muted ? 0 : 1;
    }

    get musicMuted(): boolean {
        return this._musicVolume === 0;
    }

    set sfxMuted(muted: boolean) {
        const store = getSettingStore();
        if (store) store.setSoundVolumeStore(muted ? 0 : 1);
        else this.sfxVolume = muted ? 0 : 1;
    }

    get sfxMuted(): boolean {
        return this._sfxVolume === 0;
    }
}

// 連續事件分階播放 每次 next() 進一階 超過末階持續使用末階 reset() 回到未觸發狀態
export class StagedEffectPlayer {
    private stage = -1;
    constructor(
        private bundleName: string,
        private clips: string[]
    ) {}
    next(): void {
        if (this.clips.length === 0) return;
        this.stage = Math.min(this.stage + 1, this.clips.length - 1);
        AppAudio.getInstance(this.bundleName).playEffect(this.clips[this.stage]);
    }
    reset(): void {
        this.stage = -1;
    }
}

const boundVolumeEventBundles = new Set<string>();

/**
 * 把 baseRuntimeEventBus 的 MUSIC_VOLUME_CHANGED/SOUND_VOLUME_CHANGED
 * 轉發到指定 bundle 的 AppAudio 實例，取代原本 AudioManager 元件 onLoad() 裡的訂閱邏輯。
 * 呼叫端（例如 lobby）需自行決定何時呼叫一次，通常在 initAudio() 之後；
 * 同一個 bundleName 重複呼叫只會綁定一次（可能有多個入口都會呼叫初始化）。
 */
export function bindAudioVolumeEvents(bundleName: string): void {
    if (boundVolumeEventBundles.has(bundleName)) return;
    boundVolumeEventBundles.add(bundleName);

    const audio = AppAudio.getInstance(bundleName);

    const handleMusicVolumeChanged = (musicVolume: number): void => {
        audio.musicVolume = musicVolume;
    };
    baseRuntimeEventBus.on(BASE_EVENT_TYPE.MUSIC_VOLUME_CHANGED, (e) => handleMusicVolumeChanged(e.musicVolume));
    handleMusicVolumeChanged(getSettingStore()?.musicVolume ?? 1);

    const handleSoundVolumeChanged = (soundVolume: number): void => {
        audio.sfxVolume = soundVolume;
    };
    baseRuntimeEventBus.on(BASE_EVENT_TYPE.SOUND_VOLUME_CHANGED, (e) => handleSoundVolumeChanged(e.soundVolume));
    handleSoundVolumeChanged(getSettingStore()?.soundVolume ?? 1);
}
