// dropOnly 只快停落下階段 toWinPopup 任何階段都跳到贏獎彈窗
export type SpinSkipScope = 'dropOnly' | 'toWinPopup';

let spinSkipScope: SpinSkipScope = 'toWinPopup';

export function getSpinSkipScope(): SpinSkipScope {
    return spinSkipScope;
}

/** DebugPanel 切換用 */
export function setSpinSkipScope(scope: SpinSkipScope): void {
    spinSkipScope = scope;
}
