import { _decorator, Component, Graphics, Color, Vec2, Enum, UITransform, CCInteger } from "cc";
const { ccclass, property } = _decorator;

export enum ColorOption {
    Red,
    Green,
    Blue,
    Orange,
    GreenEx,
    Pink,
    Yellow,
    skyBlue,
}

@ccclass("1002/core/framework/CustomSurroundingEffect")
export default class CustomSurroundingEffect extends Component {
    @property(Graphics)
    public graphics: Graphics | null = null;


    private glowOffset: number = 5;
    private color: Color = new Color(255, 255, 0, 255);
    private totalPathLength: number = 0;
    @property({ type: Enum(ColorOption), tooltip: "选择颜色" })
    colorOption: ColorOption = ColorOption.Blue;

    @property({
        type: CCInteger,
        tooltip: "角的半徑",
    })
    private cornerRadius: number = 10;

    @property({
        type: CCInteger,
        tooltip: "點的半徑",
    })
    private pointRadius: number = 5;

    @property({
        type: CCInteger,
        tooltip: "主点的移动速度",
    })
    private pointSpeed: number = 200; // 主点的移动速度

    @property({
        type: CCInteger,
        tooltip: "每个点之间的延迟距离",
    })
    private pointDelay: number = 3.5; // 每个点之间的延迟距离
    private pointDistance: number = 0; // 点在路径上的距离
    @property({
        type: CCInteger,
        tooltip: "每组的点数",
    })
    private pointsPerGroup: number = 59;

    @property({
        type: CCInteger,
        tooltip: "分成幾組線條",
    })
    private groupCount: number = 4;
    uiTransform: UITransform;

    override onLoad() {
        this.uiTransform = this.node.getComponent(UITransform);

        const parentUI = this.node.parent?.getComponent(UITransform);
        if (parentUI) {
            this.uiTransform.setContentSize(parentUI.contentSize);
        }

        const width = this.uiTransform.width;
        const height = this.uiTransform.height;

        this.totalPathLength =
            2 * (width - 2 * this.cornerRadius + height - 2 * this.cornerRadius) +
            Math.PI * this.cornerRadius * 2;

        // 繪製座標是 [0,width]x[0,height]，需把原點移到 parent 中心減半尺寸；
        // parent anchor 非 (0.5,0.5) 時 parent local 原點不在中心，要補回偏移
        let cx = 0;
        let cy = 0;
        if (parentUI) {
            cx = (0.5 - parentUI.anchorX) * parentUI.width;
            cy = (0.5 - parentUI.anchorY) * parentUI.height;
        }
        this.node.setPosition(cx - width / 2, cy - height / 2);
    }

    getPathPosition(pathPosition) {
        // 計算直線和圓弧的長度
        const arcLength = (Math.PI * this.cornerRadius) / 2; // 每個角的圓弧長度
        const straightLength = this.uiTransform.width - 2 * this.cornerRadius; // 頂部和底部直線部分的長度
        const straightHeight = this.uiTransform.height - 2 * this.cornerRadius; // 左側和右側直線部分的長度
        const totalPathLength = 2 * (straightLength + straightHeight) + arcLength * 4; // 路徑的總長度

        // 把 pathPosition 轉成路徑上的相對位置
        const relativePosition = pathPosition % totalPathLength;

        // 計算在路徑的哪一部分
        let currentPosition = relativePosition;
        const bottomLength = straightLength;
        const bottomRightArcStart = bottomLength;
        const bottomRightArcEnd = bottomRightArcStart + arcLength;
        const rightLength = bottomRightArcEnd + straightHeight;
        const topRightArcStart = rightLength;
        const topRightArcEnd = topRightArcStart + arcLength;
        const topLength = topRightArcEnd + straightLength;
        const topLeftArcStart = topLength;
        const topLeftArcEnd = topLeftArcStart + arcLength;
        const leftLength = topLeftArcEnd + straightHeight;
        const bottomLeftArcStart = leftLength;
        const bottomLeftArcEnd = bottomLeftArcStart + arcLength;
        // 下邊
        if (currentPosition < bottomRightArcStart) {
            // 底部直線部分
            return new Vec2(this.cornerRadius + currentPosition, 0);
        } else if (currentPosition < bottomRightArcEnd) {
            // 右下角圓弧部分
            const theta = ((currentPosition - bottomRightArcStart) / arcLength) * (Math.PI / 2);
            return new Vec2(
                this.uiTransform.width - this.cornerRadius + Math.sin(theta) * this.cornerRadius,
                (1 - Math.cos(theta)) * this.cornerRadius
            );
        } else if (currentPosition < rightLength) {
            // 右邊直線部分
            currentPosition -= bottomRightArcEnd;
            return new Vec2(this.uiTransform.width, this.cornerRadius + currentPosition);
        } else if (currentPosition < topRightArcEnd) {
            // 右上角圓弧部分
            const theta = ((currentPosition - topRightArcStart) / arcLength) * (Math.PI / 2);
            return new Vec2(
                this.uiTransform.width - (1 - Math.cos(theta)) * this.cornerRadius,
                this.uiTransform.height - this.cornerRadius + Math.sin(theta) * this.cornerRadius
            );
        } else if (currentPosition < topLength) {
            // 顶部直线部分
            currentPosition -= topRightArcEnd;
            return new Vec2(
                this.uiTransform.width - this.cornerRadius - currentPosition,
                this.uiTransform.height
            );
        } else if (currentPosition < topLeftArcEnd) {
            // 左上角圓弧部分
            const theta = ((currentPosition - topLeftArcStart) / arcLength) * (Math.PI / 2);
            return new Vec2(
                this.cornerRadius - Math.sin(theta) * this.cornerRadius,
                this.uiTransform.height - (1 - Math.cos(theta)) * this.cornerRadius
            );
        } else if (currentPosition < leftLength) {
            // 左侧直线部分
            currentPosition -= topLeftArcEnd;
            return new Vec2(0, this.uiTransform.height - this.cornerRadius - currentPosition);
        } else if (currentPosition < bottomLeftArcEnd) {
            // 左下角圓弧部分
            const theta = ((currentPosition - bottomLeftArcStart) / arcLength) * (Math.PI / 2);
            return new Vec2(
                this.cornerRadius - Math.cos(theta) * this.cornerRadius,
                0 + (1 - Math.sin(theta)) * this.cornerRadius
            );
        }
    }

    override update(dt) {
        this.pointDistance += this.pointSpeed * dt;
        this.graphics.clear();

        const totalPoints = this.groupCount * this.pointsPerGroup; // 总点数
        const groupSpacing = this.totalPathLength / this.groupCount; // 每组之间的间隔

        for (let group = 0; group < this.groupCount; group++) {
            const groupStartDistance = group * groupSpacing;
            for (let i = 0; i < this.pointsPerGroup; i++) {
                // 计算每个点的偏移量
                const offset = i * this.pointDelay;
                // 计算当前点在路径上的位置
                const pointPosition = this.getPathPosition(
                    this.pointDistance + groupStartDistance + offset
                );

                // 根据点的位置绘制点
                let ratio = i / this.pointsPerGroup;
                this.graphics.circle(pointPosition.x, pointPosition.y, this.pointRadius * ratio); // 点的半径为5

                // 计算颜色渐变
                const color = this.getColorForX(i, this.colorOption); // Cast colorOption to string
                this.graphics.fillColor = new Color(color.r, color.g, color.b, color.a * ratio); // 应用渐变颜色

                this.graphics.fill();
            }
        }
    }

    getColorForX(i: number, colorOption: ColorOption = ColorOption.Blue): Color {
        let ratio;

        ratio = i / this.pointsPerGroup;

        const breakpoint = 0.71;

        let r, g, b, a;

        switch (colorOption) {
            case ColorOption.Red:
                if (ratio < breakpoint) {
                    r = 102 + (ratio / breakpoint) * (211 - 102);
                    g = 26 + (ratio / breakpoint) * (52 - 26);
                    b = 26 + (ratio / breakpoint) * (52 - 26);
                    a = 128 + (ratio / breakpoint) * 53;
                } else {
                    r = 211 + ((ratio - breakpoint) / (1 - breakpoint)) * (255 - 211);
                    g = 52 + ((ratio - breakpoint) / (1 - breakpoint)) * (1 - 52);
                    b = 52 + ((ratio - breakpoint) / (1 - breakpoint)) * (1 - 52);
                    a = 181 + ((ratio - breakpoint) / (1 - breakpoint)) * 74;
                }
                break;

            case ColorOption.Green:
                if (ratio < breakpoint) {
                    r = 26 + (ratio / breakpoint) * (52 - 26);
                    g = 102 + (ratio / breakpoint) * (211 - 102);
                    b = 29 + (ratio / breakpoint) * (58 - 29);
                    a = 128 + (ratio / breakpoint) * 53;
                } else {
                    r = 52 + ((ratio - breakpoint) / (1 - breakpoint)) * (1 - 52);
                    g = 211 + ((ratio - breakpoint) / (1 - breakpoint)) * (255 - 211);
                    b = 58 + ((ratio - breakpoint) / (1 - breakpoint)) * (57 - 58);
                    a = 181 + ((ratio - breakpoint) / (1 - breakpoint)) * 74;
                }
                break;

            case ColorOption.Blue: // This is the original blue gradient you provided.
                if (ratio < breakpoint) {
                    r = 11 + (ratio / breakpoint) * (53 - 11);
                    g = 18 + (ratio / breakpoint) * (89 - 18);
                    b = 38 + (ratio / breakpoint) * (139 - 38);
                    a = 128 + (ratio / breakpoint) * 53;
                } else {
                    r = 53 + ((ratio - breakpoint) / (1 - breakpoint)) * (43 - 53);
                    g = 89 + ((ratio - breakpoint) / (1 - breakpoint)) * (140 - 89);
                    b = 139 + ((ratio - breakpoint) / (1 - breakpoint)) * (255 - 139);
                    a = 181 + ((ratio - breakpoint) / (1 - breakpoint)) * 74;
                }
                break;

            case ColorOption.Orange:
                if (ratio < 0.15) {
                    // 對應您的15%以下的深橘色
                    r = 255;
                    g = Math.round(91 + (ratio / 0.15) * (140 - 91)); // 從#FF5B00到#FF8C00的g值漸變
                    b = 0;
                    a = Math.round(26 + (ratio / 0.15) * (78 - 26)); // 假設Alpha漸變從26到78
                } else if (ratio >= 0.15 && ratio < 0.47) {
                    // 對應15%到47%的漸變
                    let localRatio = (ratio - 0.15) / 0.32; // 從15%到47%的局部比例
                    r = 255;
                    g = Math.round(140 + localRatio * (168 - 140)); // 從#FF8C00到#FFA800的g值漸變
                    b = 0;
                    a = Math.round(78 + localRatio * (120 - 78)); // 假設Alpha漸變從78到120
                } else {
                    // 對應47%以上的明亮橘色
                    r = 255;
                    g = 168; // #FFA800的g值
                    b = 0;
                    a = Math.round(120 + ((ratio - 0.47) / (1 - 0.47)) * (255 - 120)); // 從120漸變到255
                }
                break;

            case ColorOption.GreenEx:
                if (ratio < 0.15) {
                    // 在15%以下使用淺綠色
                    r = 24; // 0x18 轉為十進制
                    g = 242; // 0xf2 轉為十進制
                    b = 199; // 0xc7 轉為十進制
                    a = Math.round(26 + (ratio / 0.15) * (78 - 26)); // 假設Alpha漸變從26到78
                } else if (ratio >= 0.15 && ratio < 0.47) {
                    // 在15%到47%之間使用中等綠色
                    let localRatio = (ratio - 0.15) / 0.32; // 計算局部比例
                    r = 24; // 0x18 轉為十進制
                    g = 242; // 0xf2 轉為十進制
                    b = 199; // 0xc7 轉為十進制
                    a = Math.round(78 + localRatio * (120 - 78)); // 假設Alpha漸變從78到120
                } else {
                    // 超過47%使用較深綠色
                    r = 24; // 0x18 轉為十進制
                    g = 242; // 0xf2 轉為十進制
                    b = 199; // 0xc7 轉為十進制
                    a = Math.round(120 + ((ratio - 0.47) / (1 - 0.47)) * (255 - 120)); // 從120漸變到255
                }
                break;

            case ColorOption.Pink:
                if (ratio < 0.13) {
                    // 小於13%時，使用淺粉紅色並進行漸變
                    r = Math.round(251 + (ratio / 0.13) * (248 - 251));
                    g = Math.round(109 + (ratio / 0.13) * (68 - 109));
                    b = Math.round(48 + (ratio / 0.13) * (71 - 48));
                    a = Math.round(26 + (ratio / 0.15) * (78 - 26)); // 假設Alpha漸變從26到78
                } else if (ratio >= 0.13 && ratio < 0.47) {
                    // 在13%到47%之間進行漸變
                    let localRatio = (ratio - 0.13) / (0.47 - 0.13); // 計算局部比例
                    r = Math.round(248 + localRatio * (232 - 248));
                    g = Math.round(68 + localRatio * (73 - 68));
                    b = Math.round(71 + localRatio * (114 - 71));
                    a = Math.round(78 + localRatio * (120 - 78)); // 假設Alpha漸變從78到120
                } else {
                    // 大於47%時，使用深粉紅色
                    r = 232; // 0xe8 轉為十進制
                    g = 73; // 0x49 轉為十進制
                    b = 114; // 0x72 轉為十進制
                    a = Math.round(120 + ((ratio - 0.47) / (1 - 0.47)) * (255 - 120)); // 從120漸變到255
                }
                break;

            case ColorOption.skyBlue:
                // 定義起始和結束的RGB值
                const startR = 169,
                    startG = 225,
                    startB = 247;
                const endR = 98,
                    endG = 207,
                    endB = 250;

                // 計算RGB值之間的差異
                const diffR = endR - startR;
                const diffG = endG - startG;
                const diffB = endB - startB;

                // 應用比例來計算當前ratio下的RGB值
                r = Math.round(startR + ratio * diffR);
                g = Math.round(startG + ratio * diffG);
                b = Math.round(startB + ratio * diffB);
                a = 255; // 如果不需要透明度變化，則將alpha值設置為255(不透明)
                break;

            case ColorOption.Yellow:
                if (ratio < 0.15) {
                    // 深金色（帶橘）拉尾巴
                    r = 255;
                    g = Math.round(170 + (ratio / 0.15) * (205 - 170));
                    b = 0;
                    a = Math.round(40 + (ratio / 0.15) * (110 - 40));
                } else if (ratio < 0.47) {
                    let localRatio = (ratio - 0.15) / 0.32;
                    r = 255;
                    g = Math.round(205 + localRatio * (235 - 205));
                    b = 0;
                    a = Math.round(110 + localRatio * (190 - 110));
                } else {
                    // 亮金色頭部
                    let localRatio = (ratio - 0.47) / (1 - 0.47);
                    r = 255;
                    g = Math.round(235 + localRatio * (255 - 235));
                    b = Math.round(0 + localRatio * 120); // 頭部偏暖白增加亮感
                    a = Math.round(190 + localRatio * (255 - 190));
                }
                break;
        }

        return new Color(Math.round(r), Math.round(g), Math.round(b), Math.round(a));
    }

    drawPath() {
        const width = this.uiTransform.width;
        const height = this.uiTransform.height;

        this.graphics.clear();
        this.graphics.strokeColor = this.color;
        this.graphics.lineWidth = this.glowOffset * 2;

        this.graphics.arc(
            this.cornerRadius - this.glowOffset,
            height - this.cornerRadius + this.glowOffset,
            this.cornerRadius,
            Math.PI,
            Math.PI / 2,
            false
        );
        this.graphics.lineTo(width - this.cornerRadius + this.glowOffset, height + this.glowOffset);
        this.graphics.arc(
            width - this.cornerRadius + this.glowOffset,
            height - this.cornerRadius + this.glowOffset,
            this.cornerRadius,
            Math.PI / 2,
            0,
            false
        );
        this.graphics.lineTo(width + this.glowOffset, this.cornerRadius - this.glowOffset);
        this.graphics.arc(
            width - this.cornerRadius + this.glowOffset,
            this.cornerRadius - this.glowOffset,
            this.cornerRadius,
            0,
            -Math.PI / 2,
            false
        );
        this.graphics.lineTo(this.cornerRadius - this.glowOffset, -this.glowOffset);
        this.graphics.arc(
            this.cornerRadius - this.glowOffset,
            this.cornerRadius - this.glowOffset,
            this.cornerRadius,
            -Math.PI / 2,
            Math.PI,
            false
        );
        this.graphics.lineTo(-this.glowOffset, height + this.glowOffset - this.cornerRadius);
        this.graphics.stroke();
    }
}
