import { _decorator, Mask, Node, tween, Tween, type TweenEasing, UIOpacity, UITransform, Vec3 } from 'cc';
import { ReelView } from './ReelView';
import { SymbolCell } from '../symbol/SymbolCell';
import { SymbolImageManager } from '../symbol/SymbolImageManager';
import { SymbolViewMultiplier } from '../symbol/SymbolViewMultiplier';
import { SymbolExtras, SymbolState, SymbolStateLevel } from '../symbol/SymbolState';
import { MULTIPLIER_SYMBOL_IDS, SLOT_GAME_DEFINITION, SYMBOL_IDS, isMultiplierSymbolId } from '../../config/SlotGameDefinition';

const { ccclass, property } = _decorator;

@ccclass('1002/ReelView_1002')
export class ReelView_1002 extends ReelView {
    /** posList 可視格上下各留幾格緩衝；可見列 row 對應的 posList 索引是 row + BUFFER_SLOTS */
    static readonly BUFFER_SLOTS = 2;

    /**
     * 格子尺寸，取舊 NgSymbol 根節點的 contentSize。
     *
     * 那正是舊 `applySymbolVisual()` 每次換圖時 fit 進去的框，Symbols/*.prefab 也是照這個尺寸產的。
     * ReelView.prefab 的格距是 89，比這個框矮——符號本來就會略微重疊。
     */
    private static readonly CELL_WIDTH = 144;
    private static readonly CELL_HEIGHT = 107.1;

    @property({
        type: SymbolImageManager,
        tooltip: '符號顯示物件的物件池。留空時自動往上找最近的一顆（通常掛在 SlotMachineView 上）'
    })
    public symbolManager: SymbolImageManager = null!;

    /** 只在初始盤定位（tumbleFill）期間放行倍率球打雷；cascade 消除掉落（cascadeFill）不重播 */
    private allowSettleLightning: boolean = false;

    // 快停時初始盤掉落 tween 加速到這個倍率 一個 frame 內跑完
    private static readonly QUICK_STOP_TIME_SCALE = 200;
    // 正在跑的初始盤掉落 tween 快停時一併加速
    private readonly tumbleTweens = new Set<Tween<Node>>();
    private tumbleTimeScale = 1;
    // 跳過次數
    private snapEpoch = 0;

    /**
     * 拿到後端輪帶設定前的預設輪帶，值是 spriteFrames 的索引。
     *
     * 原本是 `[2, 2, 2, 5, 6, 7, 8, 9, 10, 11, 12, 14, 15, 16]`，但 1002 的 `spriteFrames` 只有
     * 15 筆（索引 0–14）：`15`／`16` 根本不存在，`10` 是沒有出現在 `SlotGameDefinition` 裡的
     * symbol_wild。改版前 `spriteFrames[15]` 拿到 undefined 指派給 `Sprite.spriteFrame` 不會報錯、
     * 只是不顯示（entry `docs/agent-pitfalls.md` 坑 #23），所以一直沒人發現。改成只用一般符號
     * （索引 0–8），全部對得到符號 id。
     */
    public override strip: number[] = [2, 2, 2, 5, 6, 7, 8, 0, 1, 3, 4, 5, 6, 7];

    /**
     * 這一轉的下注額。程式已經沒有地方讀它（原本給 coin 符號算假金額，那條路線認的 b1/b2/b3
     * 在 1002 的圖庫裡並不存在），保留只因為共用的 SlotGameMain 會對每個 reelView 寫入這個欄位。
     */
    public spinBet: number = 0;

    private static readonly SYMBOL_NAME_MAP: Record<string, string> = {
        fu: 'w1',
        caishen: 'h1',
        jin_chan: 'h2',
        wealth_tree: 'h3',
        golden_carp: 'h4',
        golden_ruyi: 'h5',
        a: 'n1',
        k: 'n2',
        q: 'n3',
        j: 'n4',
        ten: 'n5',
        red_coin: 'b1',
        green_coin: 'b2',
        blue_coin: 'b3'
    };

    protected override getSymbolNameMap(): Record<string, string> {
        return ReelView_1002.SYMBOL_NAME_MAP;
    }

    /**
     * `spriteFrames` 索引 → 符號 id 的對照。
     *
     * 外部（CascadeReelsTask、base ReelView 的輪帶邏輯）仍然以 frameIdx 溝通，但 {@link SymbolCell}
     * 認的是符號 id。這張表在 {@link buildFrameIdxToSymbolId} 一次建好，避免每次換圖都做字串比對。
     */
    private frameIdxToSymbolId: number[] = [];

    /**
     * `spriteFrames` 索引 → 附加參數的對照，只有倍率球的圖有值。
     *
     * 圖名 `symbol_m1_{tier}` 帶得出顏色階，但帶不出倍率數值（同一階有五種倍率），所以 `value`
     * 是 null——掉落途中只套 skin、不顯示數字，落定後由 {@link setMultiplierLabel} 補上真正的值。
     */
    private frameIdxToExtras: (SymbolExtras | null)[] = [];

    /**
     * 建立這一欄的格子。
     *
     * 覆寫基底的 `initSymbols()` 而不是沿用它：基底是 `instantiate(symbolPrefab)`，整顆格子連同
     * 全部美術（八個子節點的 spine）一起複製；改版後格子本身是**沒有任何美術的空殼**（只有
     * UITransform／UIOpacity／{@link SymbolCell}），要顯示什麼由 cell 向 {@link symbolManager} 租。
     * 所以連 prefab 都不需要，直接 `new Node()` 建出來最乾淨，也少一份要維護的資產。
     */
    protected override initSymbols(): void {
        // 不用遮罩裁切 爆破特效才不會被輪帶範圍切掉 改用 updateRangeVisibility 隱藏範圍外的符號
        const mask = this.getComponent(Mask);
        if (mask) mask.enabled = false;
        this.symbolManager ??= this.findManagerInParents();
        this.symbolManager?.init();
        this.buildFrameIdxToSymbolId();

        for (let i = 0; i < this.posList.length; i++) {
            const node = new Node(`cell_${i}`);
            node.layer = this.node.layer; // 坑 #3：程式建出來的節點 layer 不會自動修正，Camera 遮罩會整個擋掉
            const ui = node.addComponent(UITransform);
            ui.setContentSize(ReelView_1002.CELL_WIDTH, ReelView_1002.CELL_HEIGHT);
            ui.setAnchorPoint(0.5, 0.5);

            node.setPosition(this.posList[i].position);
            this.container.addChild(node);

            const cell = node.addComponent(SymbolCell);
            cell.setup(this.symbolManager, this);

            this.symbolNodes.push(node);
            this.symbolCells.push(cell);
            this.symbolOpacities.push(node.addComponent(UIOpacity));
            this.posIndexes.push(i);

            const stripIdx = (this.model.currentRng + i) % this.strip.length;
            this.setSymbolDisplay(i, this.strip[stripIdx]);
        }
        const half = this.cellHeightAbs() / 2;
        this.rangeTop = this.posList[ReelView_1002.BUFFER_SLOTS].position.y + half;
        this.rangeBottom = this.posList[this.posList.length - 1 - ReelView_1002.BUFFER_SLOTS].position.y - half;
        this.updateDrawOrder();
    }

    /**
     * 往上找最近的一顆 {@link SymbolImageManager}。
     *
     * 池子掛在 `SlotMachineView` 上、整台五欄共用一顆，但五欄是 SlotMachineView.prefab 裡的巢狀
     * prefab instance——要在 Inspector 把那顆池子拖進每一欄，等於每個盤面拖五次、兩個盤面十次。
     * 往上找一次就好，Inspector 上的欄位留給「這一欄要用別顆池子」這種例外情況覆寫。
     *
     * Cocos 3.8 沒有 `getComponentInParent`，所以自己走一遍父鏈。
     *
     * @returns 找到的池子；整條父鏈都沒有時為 null。
     */
    private findManagerInParents(): SymbolImageManager {
        for (let node = this.node.parent; node; node = node.parent) {
            const manager = node.getComponent(SymbolImageManager);
            if (manager) return manager;
        }
        console.warn(`[ReelView_1002] ${this.node.name} 找不到 SymbolImageManager，這一欄不會有任何符號`);
        return null!;
    }

    /**
     * 建立 `spriteFrames` 索引 → 符號 id 的對照表，順便把倍率球的圖對到它的顏色階。
     *
     * 倍率球的 40 個 id 全部對到同一個池 id（見 `SYMBOL_IDS.multiplierPool`）；圖名由
     * `symbols.frameName(id)` 產生，所以反查要正著走一遍所有 id。
     *
     * `symbol_wild` 會留在 -1：它佔著 `spriteFrames` 的一格，但 `SlotGameDefinition` 沒有宣告
     * wild，全 repo 也沒有任何程式提到它。真的被指到時會在 {@link setSymbolDisplay} 印一次警告。
     */
    private buildFrameIdxToSymbolId(): void {
        this.frameIdxToSymbolId = new Array(this.spriteFrames.length).fill(-1);
        this.frameIdxToExtras = new Array(this.spriteFrames.length).fill(null);

        const plainIds: number[] = [];
        for (let id = SYMBOL_IDS.normalMin; id <= SYMBOL_IDS.normalMax; id++) plainIds.push(id);
        plainIds.push(SYMBOL_IDS.scatter);

        for (const id of plainIds) {
            const frameName = SLOT_GAME_DEFINITION.symbols.frameName(id);
            const idx = this.frameIdxByName(frameName);
            if (idx < 0) {
                console.warn(`[ReelView_1002] spriteFrames 裡找不到 ${frameName}（symbolId=${id}），這個符號不會顯示`);
                continue;
            }
            this.frameIdxToSymbolId[idx] = id;
        }

        for (const id of MULTIPLIER_SYMBOL_IDS) {
            const idx = this.frameIdxByName(SLOT_GAME_DEFINITION.symbols.frameName(id));
            if (idx < 0) continue;
            this.frameIdxToSymbolId[idx] = SYMBOL_IDS.multiplierPool;
            this.frameIdxToExtras[idx] = { tier: SLOT_GAME_DEFINITION.symbols.resolve(id).colorTier ?? 4, value: null };
        }
    }

    /**
     * 取某個格子的 {@link SymbolCell}。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     * @returns 對應的 cell；索引越界時為 null。
     */
    private cellAt(symbolIdx: number): SymbolCell | null {
        return this.symbolCells[symbolIdx] ?? null;
    }

    /**
     * 取目前停在某個可見列上的 {@link SymbolCell}。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @returns 對應的 cell；那一列沒有格子時為 null。
     */
    private cellAtRow(row: number): SymbolCell | null {
        const idx = this.findSymbolNodeAtPosIndex(row + ReelView_1002.BUFFER_SLOTS);
        return idx < 0 ? null : this.cellAt(idx);
    }

    /**
     * 取目前停在某個可見列上的倍率球顯示物件。
     *
     * 球的演出（落雷、升級、收集）要直接對 spine 下指令，不是換狀態就能表達的，所以這裡把
     * 那顆物件拿出來。先 `flush()` 是因為呼叫端常常是「剛換完符號就要播」，不推一次的話拿到的
     * 還是上一顆。
     *
     * @param row 可見列。
     * @returns 該列的倍率球顯示物件；那一列不是球時為 null。
     */
    private multiplierViewAtRow(row: number): SymbolViewMultiplier | null {
        const cell = this.cellAtRow(row);
        if (!cell) return null;
        cell.flush();
        const view = cell.getView();
        return view instanceof SymbolViewMultiplier ? view : null;
    }

    /**
     * 把某一格換成指定的符號，並清掉上一個符號留下的附加狀態。
     *
     * 外部仍以 frameIdx 溝通（base 的輪帶邏輯與 CascadeReelsTask 都是），這裡翻譯成符號 id 交給
     * {@link SymbolCell}。
     *
     * scatter 的 idle 在這裡打開而不是等落定——1002 沒有 `revealScatter()`，舊版就是在
     * `setSymbolDisplay()` 裡判斷圖名等於 `symbol_scatter` 就 `showScatter()`，這裡維持同樣的時機。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     * @param stripIdx 要顯示的圖在 spriteFrames 裡的索引。
     */
    override setSymbolDisplay(symbolIdx: number, stripIdx: number): void {
        const cell = this.cellAt(symbolIdx);
        if (!cell) return;

        cell.clearState(SymbolStateLevel.Win);
        cell.clearState(SymbolStateLevel.High);

        const symbolId = this.frameIdxToSymbolId[stripIdx] ?? -1;
        if (symbolId < 0) {
            console.warn(`[ReelView_1002] frameIdx=${stripIdx} 對不到任何符號 id，該格不會換圖`);
            return;
        }

        cell.setSymbolId(symbolId);
        cell.setExtras(this.nextExtras(cell, symbolId, stripIdx));
        cell.setState(symbolId === SYMBOL_IDS.scatter ? SymbolState.Idle : SymbolState.None, SymbolStateLevel.Idle);
    }

    /**
     * 換圖之後這一格該帶什麼附加參數。
     *
     * **倖存的倍率球要留住自己的數字。** cascade 掉落時整顆球往下移，`setSymbolDisplay()` 會再被
     * 呼叫一次；如果照圖名重設參數，數值會在掉落途中消失、落定才又出現。舊版是在
     * `setSymbolDisplay()` 開一個 `isMultiplierBallActive()` 的特例直接 return 來避免，這裡改成
     * 「還是球而且已經知道數值，就沿用原本的參數」——同樣的效果，但不必為此在換圖路徑上開特例。
     *
     * @param cell 這一格。
     * @param symbolId 換過去的符號 id。
     * @param stripIdx 圖在 spriteFrames 裡的索引。
     * @returns 要套用的附加參數；非倍率球時為 null。
     */
    private nextExtras(cell: SymbolCell, symbolId: number, stripIdx: number): SymbolExtras | null {
        if (!isMultiplierSymbolId(symbolId)) return null;
        const current = cell.getExtras();
        if (current && current.value != null) return current;
        return this.frameIdxToExtras[stripIdx] ?? null;
    }

    /**
     * 符號落定的收尾：倍率球在初始盤落定時打雷。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     */
    protected override onSymbolSettled(symbolIdx: number): void {
        if (!this.allowSettleLightning) return;
        const cell = this.cellAt(symbolIdx);
        if (!cell || !isMultiplierSymbolId(cell.getSymbolId())) return;

        const posIdx = this.posIndexes[symbolIdx];
        const bottom = this.posList.length - 1 - ReelView_1002.BUFFER_SLOTS;
        if (posIdx < ReelView_1002.BUFFER_SLOTS || posIdx > bottom) return;

        cell.flush();
        const view = cell.getView();
        if (view instanceof SymbolViewMultiplier) void view.playUp();
    }

    /** 消除爆破的基準時長（秒），spine 的 timeScale 隨三段速的 explode 時長縮放 */
    private static readonly ELIMINATE_BASE_TIME = 0.3;

    /**
     * 消除爆破：把要消掉的格子切到 {@link SymbolState.Erase}，播完再交給 base 做收尾記帳。
     *
     * 改版前是逐格問 `NgSymbol.hasEliminateFx()`「這格有沒有特效可播」，有才播 spine、沒有就退回
     * base 的縮小 tween。現在不需要那個分岔：`Erase` 狀態缺項時物件池會自動 fallback 回 `Normal`
     * （見 `SymbolImageManager.registerPrefab`），呼叫端一律當成有特效處理即可。
     *
     * base 的 `explode()` 仍然要跑——它負責把節點的 opacity 歸零、scale 復位，讓格子能重複使用。
     * 這裡用 `explodeTime` 0 呼叫，只取那份記帳、不再播一次縮小動畫。
     *
     * @param rows 要消除的可見列。
     * @param explodeTime 這一段的時長（秒），spine 的 timeScale 依它縮放。
     * @returns 全部消除演出結束後 resolve。
     */
    override async explode(rows: number[], explodeTime: number): Promise<void> {
        const duration = Math.max(explodeTime, 0.05);
        const speed = ReelView_1002.ELIMINATE_BASE_TIME / duration;
        const tasks: Promise<void>[] = [];
        const epoch = this.snapEpoch;

        for (const row of rows) {
            const cell = this.cellAtRow(row);
            if (!cell) continue;
            cell.setState(SymbolState.Erase, SymbolStateLevel.High);
            cell.flush();
            cell.setTimeScale(speed);
            tasks.push(cell.playCurrentStateOnce(duration));
        }

        await Promise.all(tasks);
        if (epoch !== this.snapEpoch) return;
        await super.explode(rows, 0);
        if (epoch !== this.snapEpoch) return;

        // 爆破結束後把 Erase 讓出來，格子回到由輪軸旗標推算的預設狀態，才能被補牌重複使用
        for (const row of rows) this.cellAtRow(row)?.clearState(SymbolStateLevel.High);
    }

    /** 中獎演出的基準時長（秒），timeScale 隨三段速的 winFx 時長縮放（同 explode 的做法） */
    private static readonly WIN_FX_BASE_TIME = 1.6;

    /**
     * 爆破前先對指定列各播一次中獎演出：切到 {@link SymbolState.WinAnimation}，等它播完。
     *
     * 狀態設在 {@link SymbolStateLevel.Win} 層——高於轉動邏輯的 `Reel` 層與 scatter 的 `Idle` 層，
     * 所以不管當下在顯示什麼都會被蓋過去；也因為只設這一層，中獎演出結束時只要 `clearState(Win)`
     * 就能乾淨退場，底下的 idle 會自己浮回來。
     *
     * @param rows 中獎的可見列。
     * @param winFxTime 這一段的時長（秒），timeScale 依它縮放；預設用基準值。
     * @returns 全部播完後 resolve。
     */
    playWinFx(rows: number[], winFxTime = ReelView_1002.WIN_FX_BASE_TIME): Promise<void> {
        const duration = Math.max(winFxTime, 0.05);
        const speed = ReelView_1002.WIN_FX_BASE_TIME / duration;
        const promises: Promise<void>[] = [];

        for (const row of rows) {
            const cell = this.cellAtRow(row);
            if (!cell) continue;
            cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
            cell.flush();
            cell.setTimeScale(speed);
            promises.push(cell.playCurrentStateOnce(duration));
        }

        return Promise.all(promises).then(() => undefined);
    }

    /**
     * 把某一列切到中獎狀態，供共用的 `SlotMachineView.playSymbolWins()` 連線演出路徑使用。
     *
     * 1002 自己的消除流程走的是 {@link playWinFx}，不經過這裡。改版前這一支其實是**空轉的**：
     * 它讀的 `symbolSpines` 陣列從宣告到現在沒有任何地方 push 過，永遠是空的，所以一律 return
     * false。接到格子上之後才真的會動。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @param _animName 保留參數，改版後動畫由 prefab 上的 `SymbolViewSpine` 決定。
     * @param loop 是否循環；false 時才會觸發 `onComplete`。
     * @param onComplete 播完的回呼。
     * @returns 有成功切到中獎狀態為 true；那一列沒有格子時為 false。
     */
    playWinAnim(row: number, _animName: string, loop: boolean = true, onComplete?: () => void): boolean {
        const cell = this.cellAtRow(row);
        if (!cell) return false;

        cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
        cell.flush();

        if (!loop && onComplete) {
            void cell.playCurrentStateOnce(ReelView_1002.WIN_FX_BASE_TIME).then(onComplete);
        }
        return true;
    }

    /**
     * 結束中獎演出：把 {@link SymbolStateLevel.Win} 層讓出來，格子自動回到預設狀態。
     *
     * 改版前是逐格把 spine 切回各自的 `*stop` 動畫（需要一張 `SPINE_STOP_ANIM` 對照表，而且表裡
     * 的名字 h2/n1/w1/b1 在 1002 的素材裡根本不存在）；現在不需要——退出 `WinAnimation` 狀態時
     * 物件池會把中獎用的顯示物件收回去、換回 `Normal` 那一顆，靜止外觀本來就是它。
     */
    stopAllWinAnims(): void {
        for (const cell of this.symbolCells) cell?.clearState(SymbolStateLevel.Win);
    }

    /**
     * DebugPanel「Symbol 縮放」呼叫，套用到這一欄目前所有的格子。
     *
     * @param scale 縮放倍率，1 為原始大小。
     */
    setSymbolScale(scale: number): void {
        for (const cell of this.symbolCells) cell?.setScaleMultiplier(scale);
    }

    /**
     * 調整這一欄所有格子的動畫播放速度。
     *
     * @param scale 倍率，1 為原速、0 為凍結。
     */
    setSymbolSpinesTimeScale(scale: number): void {
        for (const cell of this.symbolCells) cell?.setTimeScale(scale);
    }

    /**
     * 整欄重置：歸還所有顯示物件、清掉狀態與倍率球參數。
     *
     * 對應舊 `NgSymbol` 那一整排 `hide()`／`hideMultiplierBall()`／`hideScatter()`。
     */
    resetAllCells(): void {
        for (const cell of this.symbolCells) cell?.resetCell();
    }

    /**
     * 倍率球：設定某一列的球參數。
     *
     * @param row 可見列（0..4，由上往下）。
     * @param value 倍率值；null 表示這一格不是球，清掉參數。
     * @param _side 角色側。1002 的 `symbol_m` 只有一套 skin，這個參數只為了跟呼叫端相容而保留。
     * @param tier 顏色階。
     */
    setMultiplierLabel(row: number, value: number | null, _side: number = 1, tier: number = 4): void {
        const cell = this.cellAtRow(row);
        if (!cell) return;
        cell.setExtras(value == null ? null : { tier, value });
    }

    /**
     * 倍率球升級演出。
     *
     * 新的 skin 與數字由 `playMul` 在動畫第 200ms 自己換（企劃 §20/§17），所以這裡**不先**寫進
     * 格子——寫了會變成瞬間換值。等動畫跑完才把格子記的參數補上，之後若這顆顯示物件被換掉，
     * 重租的那顆才會是新的樣子。
     *
     * @param row 可見列。
     * @param _side 角色側，1002 不使用。
     * @param newTier 新的顏色階。
     * @param newValue 新的倍率值。
     */
    playMultiplierUpgrade(row: number, _side: number, newTier: number, newValue: number): void {
        const cell = this.cellAtRow(row);
        const view = this.multiplierViewAtRow(row);
        if (!cell || !view) return;
        void view.playMul(newTier, newValue).then(() => cell.setExtras({ tier: newTier, value: newValue }));
    }

    /**
     * 倍率球被收集的演出。
     *
     * @param row 可見列。
     */
    playMultiplierCollect(row: number): void {
        this.multiplierViewAtRow(row)?.playCollect();
    }

    /**
     * scatter 中獎演出。
     *
     * scatter 沒有專屬狀態——它的中獎演出跟一般符號一樣是 `WinAnimation`，差別只在資產不同，
     * 而資產差異已經由「每個符號一支 prefab」吸收掉了。
     *
     * @param row 可見列。
     */
    playScatterWin(row: number): void {
        const cell = this.cellAtRow(row);
        if (!cell) return;
        cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
        cell.flush();
    }

    /**
     * 取某個格位的世界座標，飄分數字與倍率球收集軌跡要用它定位。
     *
     * @param posIdx posList 的索引（可見列 + {@link ReelView_1002.BUFFER_SLOTS}）。
     * @returns 該格位的世界座標。
     */
    getCellWorldPosition(posIdx: number): Vec3 {
        return this.posList[posIdx].getWorldPosition();
    }

    override async tumbleClear(clearTime: number, rowDelay: number = 0.05, clearEase: TweenEasing = 'quadIn'): Promise<void> {
        const promises: Promise<void>[] = [];
        const dropOrder = [6, 5, 4, 3, 2];

        const cellHeight = this.posList[1].position.y - this.posList[2].position.y;
        const boardHeight = cellHeight * 5;
        // 物理式掉落：整批同樣掉出 boardHeight 這段距離，用重力反推的耗時取代固定 clearTime，
        // 每行仍保留原本的漸快 stagger 手感（0.75 + i*0.125）疊在物理耗時之上。
        const physicsClearTime = this.physicsFallDuration(boardHeight, this.cellHeightAbs(), clearTime);

        for (let i = 0; i < dropOrder.length; i++) {
            const posIdx = dropOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;
            const node = this.symbolNodes[symIdx];
            const opacity = this.symbolOpacities[symIdx];
            const targetY = this.posList[posIdx].position.y - boardHeight;

            const rowClearTime = physicsClearTime * (0.75 + i * 0.125);

            promises.push(
                new Promise<void>((resolve) => {
                    Tween.stopAllByTarget(node);
                    this.startTumbleTween(
                        tween(node)
                            .delay(i * rowDelay)
                            .to(rowClearTime, { position: new Vec3(0, targetY, 0) }, { easing: clearEase })
                            .call(() => {
                                opacity.opacity = 0;
                                resolve();
                            })
                    );
                })
            );
        }
        await Promise.all(promises);
    }

    /** 落地果凍效果（squash）的關鍵影格：scale 是每格相對 (1,1) 的目標值，intensity=1 時為原始美術數值（跟 1001 對齊） */
    private static readonly SQUASH_KEYFRAMES: { time: number; scale: [number, number]; easing: TweenEasing }[] = [
        { time: 0.11, scale: [1.45, 0.66], easing: 'quadOut' },
        { time: 0.12, scale: [0.8, 1.25], easing: 'quadOut' },
        { time: 0.08, scale: [1.25, 0.8], easing: 'quadOut' },
        { time: 0.09, scale: [0.9, 1.12], easing: 'quadOut' },
        { time: 0.08, scale: [1, 1], easing: 'sineOut' }
    ];

    /** DebugPanel「果凍效果」滑桿：0=關閉、1=原始美術數值、可調更誇張，下次 spin 生效；預設 1（跟 1001 現行值對齊） */
    private squashIntensity: number = 1;

    /**
     * 設定落地果凍效果的強度，下次 spin 生效。
     *
     * @param intensity 0 = 關閉、1 = 原始美術數值，可以調更大。
     */
    setSquashIntensity(intensity: number): void {
        this.squashIntensity = intensity;
    }

    /**
     * 把果凍效果的關鍵影格接到既有的 tween 後面。
     *
     * @param t 要接續的 tween。
     * @returns 接好的 tween；強度為 0 時原樣回傳。
     */
    private landingSquash(t: Tween<Node>): Tween<Node> {
        if (this.squashIntensity <= 0) return t;
        for (const kf of ReelView_1002.SQUASH_KEYFRAMES) {
            const sx = 1 + (kf.scale[0] - 1) * this.squashIntensity;
            const sy = 1 + (kf.scale[1] - 1) * this.squashIntensity;
            t = t.to(kf.time, { scale: new Vec3(sx, sy, 1) }, { easing: kf.easing });
        }
        return t;
    }

    /**
     * 開局整盤落下：用新的符號名稱把可見盤面從上方重新掉滿。
     *
     * 每顆從自己落點正上方一個盤面高度落下，落下距離相同，由下往上依序起跑與落定。
     *
     * @param newSymbolNames 由上到下的可見列符號名稱。
     * @param fillTime 掉落一格高度的參考耗時（秒），實際耗時依落下距離以重力反推。
     * @param rowDelay 相鄰兩列起跑的間隔（秒）。
     * @param onBottomLanded 最下面那顆到達 targetY 時呼叫（停輪音），不等落地彈跳。
     * @param fillEase 掉落段的 easing。
     * @returns 全部符號演完落地彈跳與果凍壓扁後 resolve。
     */
    override async tumbleFill(
        newSymbolNames: string[],
        fillTime: number,
        rowDelay: number = 0.05,
        onBottomLanded?: () => void,
        fillEase: TweenEasing = 'quadIn'
    ): Promise<void> {
        this.resetAllCells(); // 新盤貼圖／掉落前重置所有重用節點，包含 buffer
        // onSymbolSettled 在落定 tween 的 .call 同步觸發(仍在此 await 內),放行窗口涵蓋整個初始盤落定
        this.allowSettleLightning = true;
        const cellHeight = this.posList[1].position.y - this.posList[2].position.y;
        const promises: Promise<void>[] = [];
        const firstPos = ReelView_1002.BUFFER_SLOTS;
        const lastPos = this.posList.length - 1 - ReelView_1002.BUFFER_SLOTS;
        const fillOrder: number[] = [];
        for (let p = lastPos; p >= firstPos; p--) fillOrder.push(p);
        const boardHeight = this.posList[firstPos].position.y - this.posList[lastPos].position.y + cellHeight;
        let bottomAssigned = false;

        for (let i = 0; i < fillOrder.length; i++) {
            const posIdx = fillOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;
            // fillOrder 由下往上，第一顆實際落下的就是最下面那顆
            const isBottom = !bottomAssigned;
            bottomAssigned = true;

            const nameIdx = fillOrder.length - 1 - i;
            const srcName = newSymbolNames[nameIdx];
            const imgName = ReelView_1002.SYMBOL_NAME_MAP[srcName] ?? srcName;
            let frameIdx = this.frameIdxByName(imgName);
            if (frameIdx < 0) {
                console.warn(
                    `[tumbleFill] no spriteFrame for name="${imgName}" (src="${srcName}"), sprite frames:`,
                    this.spriteFrames.map((f) => f?.name)
                );
                frameIdx = 0;
            }

            const targetY = this.posList[posIdx].position.y;
            const startY = targetY + boardHeight;

            this.setSymbolDisplay(symIdx, frameIdx);
            this.symbolOpacities[symIdx].opacity = 255;
            this.symbolNodes[symIdx].setScale(1, 1, 1);
            this.symbolNodes[symIdx].setPosition(0, startY, 0);

            const node = this.symbolNodes[symIdx];
            const cellHeightAbs = this.cellHeightAbs();
            const physicsFillTime = this.physicsFallDuration(targetY - startY, cellHeightAbs, fillTime);
            promises.push(
                new Promise<void>((resolve) => {
                    Tween.stopAllByTarget(node);
                    let pending = 2; // 回彈與壓扁都演完才算
                    const partDone = () => {
                        if (--pending === 0) resolve();
                    };
                    const fallTween = tween(node)
                        .delay(i * rowDelay)
                        .to(physicsFillTime, { position: new Vec3(0, targetY, 0) }, { easing: fillEase })
                        .call(() => {
                            if (isBottom) onBottomLanded?.();
                            this.onSymbolSettled(symIdx);
                            this.startTumbleTween(this.landingSquash(tween(node)).call(partDone));
                        });
                    this.startTumbleTween(this.appendLandingBounce(fallTween, targetY, cellHeightAbs).call(partDone));
                })
            );
        }
        await Promise.all(promises);
        this.allowSettleLightning = false;
    }

    /**
     * 開始跑一條初始盤掉落 tween，並登記起來讓快停時能加速。
     *
     * 快停已經觸發的話，後面才開始的掉落也直接用快停倍率跑。
     *
     * @param chain 已經接好所有動作、還沒 start 的 tween。
     */
    private startTumbleTween(chain: Tween<Node>): void {
        this.tumbleTweens.add(chain);
        chain
            .call(() => this.tumbleTweens.delete(chain))
            .timeScale(this.tumbleTimeScale)
            .start();
    }

    /** 跳過：停掉進行中的動畫 盤面直接設成最終樣子 */
    public snapToBoard(frameIdxes: number[]): void {
        this.snapEpoch++;
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const node = this.symbolNodes[i];
            Tween.stopAllByTarget(node);
            node.setScale(1, 1, 1);
            node.setPosition(0, this.posList[this.posIndexes[i]].position.y, 0);
            const cell = this.cellAt(i);
            cell?.clearState(SymbolStateLevel.Win);
            cell?.clearState(SymbolStateLevel.High);
            const view = cell?.getView();
            if (view instanceof SymbolViewMultiplier) view.interrupt();
        }
        for (let row = 0; row < frameIdxes.length; row++) {
            const idx = this.findSymbolNodeAtPosIndex(row + ReelView_1002.BUFFER_SLOTS);
            if (idx < 0) continue;
            this.symbolOpacities[idx].opacity = 255;
            this.setSymbolDisplay(idx, frameIdxes[row]);
        }
        this.tumbleTweens.clear();
        this.tumbleTimeScale = 1;
        this.updateDrawOrder();
    }

    /**
     * 快停：初始盤的清空與落下立刻跑完，包含還在排隊等延遲的與之後才開始的。
     *
     * 只是把 tween 時間加速，所以落定回呼、停輪音、Promise 都照常觸發，不會卡住。
     */
    public quickStopTumble(): void {
        this.tumbleTimeScale = ReelView_1002.QUICK_STOP_TIME_SCALE;
        for (const chain of Array.from(this.tumbleTweens)) chain.timeScale(this.tumbleTimeScale);
    }

    /**
     * 初始盤掉落階段結束，還原正常速度給下一轉用。
     */
    public resetQuickStopTumble(): void {
        this.tumbleTimeScale = 1;
        this.tumbleTweens.clear();
    }

    protected override update(dt: number): void {
        super.update(dt);
        this.updateRangeVisibility();
    }

    // 可視範圍的上下邊界 建立格子時算好
    private rangeTop = 0;
    private rangeBottom = 0;
    // 上一幀各格的 y 沒動的格子就不用再判斷
    private readonly rangeLastY: number[] = [];

    /** 只有進到可視範圍的符號才顯示 其餘整顆透明 不管是不是緩衝格 */
    private updateRangeVisibility(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const y = this.symbolNodes[i].position.y;
            if (this.rangeLastY[i] === y) continue;
            this.rangeLastY[i] = y;
            this.cellAt(i)?.setRangeHidden(y > this.rangeTop || y < this.rangeBottom);
        }
    }
}
